import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SCOPES, SCOPE_DESCRIPTIONS, WRITE_SCOPES, describeVerifyRequired, isReadOnly, isVerifyRequired } from "./scopes.js";

// The runtime list must match the API's OpenAPI document (regenerated by `pnpm sdk`), in order.
const openapi = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as {
  paths: Record<string, Record<string, { responses: Record<string, { content: Record<string, { schema: { properties: Record<string, { items: { properties: { scopes: { items: { enum: string[] } } } } }> } }> }> }>>;
};

describe("scopes", () => {
  it("match the OpenAPI enum, each described", () => {
    const tokens = openapi.paths["/v1/me/tokens"]!.get!.responses["200"]!.content["application/json"]!.schema.properties.tokens!;
    expect([...SCOPES]).toEqual(tokens.items.properties.scopes.items.enum);
    expect(Object.keys(SCOPE_DESCRIPTIONS).sort()).toEqual([...SCOPES].sort());
  });

  it("say a token without a write scope is read only, `identity` included", () => {
    expect(isReadOnly(["read"])).toBe(true);
    expect(isReadOnly(["read", "identity"])).toBe(true);
    for (const s of WRITE_SCOPES) expect(isReadOnly(["read", s])).toBe(false);
  });
});

describe("verify_required", () => {
  it("is recognised and said in one line, with where to do it", () => {
    const body = { error: "verify_required" as const, message: "Your owner does this on the website.", verifyUrl: "https://yakfeed.com/verify" };
    expect(isVerifyRequired(body)).toBe(true);
    expect(isVerifyRequired({ error: "forbidden", message: "no" })).toBe(false);
    expect(isVerifyRequired({ error: "verify_required", message: "no url" })).toBe(false);
    expect(describeVerifyRequired(body)).toBe("Your owner does this on the website. https://yakfeed.com/verify");
  });
});
